/* Busca Vaga — utilidades comuns aos extratores (vem do config.json, atualizável sem APK novo).
   Cada extrator devolve JSON.stringify([{titulo, empresa, local, cidade, uf, modalidade, contrato, data, dataTexto, link, descricao}]) */
var BV = (function () {
  function t(el) { return el ? (el.innerText || el.textContent || '').replace(/\s+/g, ' ').trim() : ''; }
  function q(root, sel) { try { return (root || document).querySelector(sel); } catch (e) { return null; } }
  function qa(root, sel) { try { return Array.prototype.slice.call((root || document).querySelectorAll(sel)); } catch (e) { return []; } }
  function tq(root, sel) { return t(q(root, sel)); }
  function abs(h) { try { return h ? new URL(h, document.baseURI).href : ''; } catch (e) { return h || ''; } }
  function pad(n) { return (n < 10 ? '0' : '') + n; }
  function iso(d) { return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()); }
  function norm(s) { return (s || '').toString().normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase(); }
  /* "2026-10-05", "05/10/2026", "13/10", "hoje", "ontem", "há 3 dias", "Há 1 semana" -> yyyy-mm-dd */
  function data(s) {
    s = norm(s);
    if (!s) return '';
    var m = s.match(/(\d{4})[-\/](\d{2})[-\/](\d{2})/); if (m) return m[1] + '-' + m[2] + '-' + m[3];
    m = s.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/); if (m) return m[3] + '-' + pad(+m[2]) + '-' + pad(+m[1]);
    var hoje = new Date();
    m = s.match(/(\d{1,2})\/(\d{1,2})(?!\/)/);
    if (m) { var d = new Date(hoje.getFullYear(), +m[2] - 1, +m[1]); if (d - hoje > 86400000 * 2) d.setFullYear(d.getFullYear() - 1); return iso(d); }
    var meses = ['jan', 'fev', 'mar', 'abr', 'mai', 'jun', 'jul', 'ago', 'set', 'out', 'nov', 'dez'];
    m = s.match(/(\d{1,2})\s+(?:de\s+)?(jan|fev|mar|abr|mai|jun|jul|ago|set|out|nov|dez)/);
    if (m) { var d2 = new Date(hoje.getFullYear(), meses.indexOf(m[2]), +m[1]); if (d2 - hoje > 86400000 * 2) d2.setFullYear(d2.getFullYear() - 1); return iso(d2); }
    if (/\bhoje\b|agora|hora|minuto|today/.test(s)) return iso(hoje);
    if (/\bontem\b|yesterday/.test(s)) return iso(new Date(hoje - 86400000));
    m = s.match(/(\d+)\+?\s*(dia|semana|mes|meses|ano|day|week|month)/);
    if (m) {
      var n = +m[1], u = m[2];
      var dias = (u.indexOf('sem') === 0 || u === 'week') ? 7 : ((u.indexOf('mes') === 0 || u === 'month') ? 30 : (u === 'ano' ? 365 : 1));
      return iso(new Date(hoje - n * dias * 86400000));
    }
    return '';
  }
  function modalidade(s) {
    s = norm(s);
    if (/hibrid|hybrid/.test(s)) return 'hibrido';
    if (/home.?office|remot|teletrabalho|remote/.test(s)) return 'remoto';
    if (/presencial|on-site|onsite/.test(s)) return 'presencial';
    return '';
  }
  function contrato(s) {
    s = norm(s);
    var out = [];
    if (/\bclt\b|efetivo|vacancy_type_effective|full_time|tempo integral/.test(s)) out.push('CLT');
    if (/\bpj\b|pessoa juridica|legal_entity|contractor/.test(s)) out.push('PJ');
    if (/estagi|internship/.test(s)) out.push('Estágio');
    if (/temporari|temporary/.test(s)) out.push('Temporário');
    if (/aprendiz|apprentice/.test(s)) out.push('Jovem Aprendiz');
    if (/trainee/.test(s)) out.push('Trainee');
    if (/freelanc|autonom/.test(s)) out.push('Freelancer');
    if (/meio periodo|part.?time/.test(s)) out.push('Meio período');
    return out.join(',');
  }
  /* Vagas declaradas em JSON-LD (schema.org JobPosting) */
  function ld() {
    var out = [];
    function walk(o) {
      if (!o || typeof o !== 'object') return;
      if (Array.isArray(o)) { o.forEach(walk); return; }
      var ty = o['@type'];
      if (ty === 'JobPosting' || (Array.isArray(ty) && ty.indexOf('JobPosting') >= 0)) {
        var loc = Array.isArray(o.jobLocation) ? o.jobLocation[0] : o.jobLocation;
        var a = (loc && loc.address) || {};
        var desc = (o.description || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
        var org = o.hiringOrganization;
        out.push({ titulo: o.title || '', empresa: (org && (org.name || (typeof org === 'string' ? org : ''))) || '',
          cidade: a.addressLocality || '', uf: a.addressRegion || '', local: '',
          modalidade: o.jobLocationType === 'TELECOMMUTE' ? 'remoto' : modalidade(desc.slice(0, 400)),
          contrato: contrato(String(o.employmentType || '')), data: data(o.datePosted || ''), dataTexto: '',
          link: abs(o.url || ''), descricao: desc.slice(0, 300) });
      }
      Object.keys(o).forEach(function (k) { if (o[k] && typeof o[k] === 'object') walk(o[k]); });
    }
    qa(document, 'script[type="application/ld+json"]').forEach(function (s) { try { walk(JSON.parse(s.textContent)); } catch (e) {} });
    return out;
  }
  function saida(v) {
    var vistos = {};
    return JSON.stringify((v || []).filter(function (x) {
      if (!x || !x.titulo) return false;
      x.titulo = String(x.titulo).replace(/\s+/g, ' ').trim();
      var k = x.link || (x.titulo + '|' + x.empresa);
      if (vistos[k]) return false; vistos[k] = 1; return true;
    }).map(function (x) {
      ['empresa', 'local', 'cidade', 'uf', 'modalidade', 'contrato', 'data', 'dataTexto', 'link', 'descricao'].forEach(function (c) {
        x[c] = x[c] == null ? '' : String(x[c]).trim();
      });
      return x;
    }));
  }
  var busca = (typeof BV_BUSCA !== 'undefined') ? BV_BUSCA : {};
  return { t: t, q: q, qa: qa, tq: tq, abs: abs, data: data, norm: norm, modalidade: modalidade, contrato: contrato, ld: ld, saida: saida, busca: busca };
})();

