(function () {
  var v = BV.qa(document, 'li').filter(function (li) { return BV.q(li, '.base-search-card__title'); }).map(function (li) {
    var local = BV.tq(li, '.job-search-card__location');
    var tm = BV.q(li, 'time');
    var a = BV.q(li, 'a.base-card__full-link') || BV.q(li, 'a[href*="/jobs/view/"]');
    return { titulo: BV.tq(li, '.base-search-card__title'), empresa: BV.tq(li, '.base-search-card__subtitle'), local: local,
      modalidade: BV.modalidade(local), data: tm ? (tm.getAttribute('datetime') || BV.data(BV.t(tm))) : '', dataTexto: BV.t(tm),
      link: a ? a.href.split('?')[0] : '' };
  });
  return BV.saida(v.length ? v : BV.ld());
})()

(function () {
  var tipos = { vacancy_type_effective: 'CLT', vacancy_type_internship: 'Estágio', vacancy_type_temporary: 'Temporário',
    vacancy_legal_entity: 'PJ', vacancy_type_legal_entity: 'PJ', vacancy_type_apprentice: 'Jovem Aprendiz', vacancy_type_trainee: 'Trainee',
    vacancy_type_freelancer: 'Freelancer', vacancy_type_autonomous: 'Freelancer', vacancy_type_part_time: 'Meio período',
    vacancy_type_summer: 'Temporário', vacancy_type_talent_pool: '', vacancy_type_associate: '', vacancy_type_lecturer: '', vacancy_type_volunteer: '' };
  var lista = [];
  try {
    var d = JSON.parse(BV.q(document, '#__NEXT_DATA__').textContent);
    lista = ((d.props.pageProps.initialJobList || {}).data) || [];
  } catch (e) {}
  var v = lista.map(function (j) {
    var wt = j.workplaceType === 'remote' ? 'remoto' : j.workplaceType === 'hybrid' ? 'hibrido' : j.workplaceType === 'on-site' ? 'presencial' : '';
    return { titulo: j.name, empresa: j.careerPageName, cidade: j.city, uf: j.state, local: [j.city, j.state].filter(Boolean).join(' - '),
      modalidade: wt, contrato: (j.type in tipos) ? tipos[j.type] : BV.contrato(j.type), data: BV.data(j.publishedDate || ''), link: j.jobUrl,
      descricao: (j.description || '').slice(0, 300) };
  });
  return BV.saida(v.length ? v : BV.ld());
})()

(function () {
  var b = BV.busca || {};
  var v = BV.qa(document, 'li[data-offer-item]').map(function (li) {
    var a = BV.q(li, 'h2 a') || BV.q(li, 'a[href*="/vagas/"]');
    var local = '';
    BV.qa(li, 'p').forEach(function (p) { if (!local && BV.q(p, '.i_job_location')) local = BV.t(p); });
    var maisCidades = /\+\s*\d+\s*cidade/i.test(local);
    local = local.replace(/^\d+\s*vagas?\s*-\s*/i, '').replace(/\+\s*\d+\s*cidades?/i, '').trim();
    var bate = (li.getAttribute('data-matches-filter') || '').toLowerCase() === 'true';
    var tag = BV.tq(li, 'span.tag');
    var titulo = a ? (a.getAttribute('title') || BV.t(a)) : '';
    return { titulo: titulo, empresa: BV.tq(li, 'p.mb-2 span'),
      cidade: bate && b.cidade ? b.cidade : (maisCidades ? '' : local), uf: bate && b.uf ? b.uf : '', local: local + (maisCidades ? ' e outras cidades' : ''),
      modalidade: BV.modalidade(titulo + ' ' + local + ' ' + tag), contrato: BV.contrato(BV.t(li)), data: BV.data(tag), dataTexto: tag,
      link: a ? a.href : '' };
  });
  return BV.saida(v.length ? v : BV.ld());
})()

(function () {
  var v = BV.qa(document, '.js_vacancyLoad').map(function (c) {
    var dv = BV.q(c, '.js_date');
    var titulo = BV.tq(c, '.js_vacancyTitle') || BV.tq(c, 'h2');
    var local = BV.tq(c, 'div.text-body.mb-8').replace(/,\s*\d+\s*Km.*$/i, '');
    var txt = BV.t(c);
    var tb = BV.qa(c, 'div.text-body').filter(function (d) { return d.className.indexOf('mb-8') < 0; });
    var emp = tb.length ? BV.t(tb[0]) : '';
    var a0 = BV.q(c, 'a');
    var link = c.getAttribute('href') || (a0 ? a0.getAttribute('href') : '');
    return { titulo: titulo, empresa: emp, local: local, modalidade: BV.modalidade(txt.replace(titulo, '')), contrato: BV.contrato(txt),
      data: dv ? BV.data(dv.getAttribute('data-value')) : '', link: BV.abs(link) };
  });
  return BV.saida(v.length ? v : BV.ld());
})()

(function () {
  var v = BV.qa(document, 'li.vaga').map(function (li) {
    var a = BV.q(li, 'h2.cargo a') || BV.q(li, 'a.link-detalhes-vaga');
    var local = BV.tq(li, '.vaga-local').replace(/A empresa aceita.*$/i, '').trim();
    return { titulo: a ? (a.getAttribute('title') || BV.t(a)) : '', empresa: BV.tq(li, '.emprVaga'), local: local,
      modalidade: BV.modalidade(local), contrato: BV.contrato(BV.tq(li, '.nivelVaga')),
      data: BV.data(BV.tq(li, '.data-publicacao')), dataTexto: BV.tq(li, '.data-publicacao'), link: a ? a.href : '',
      descricao: BV.tq(li, '.detalhes') };
  });
  return BV.saida(v.length ? v : BV.ld());
})()

(function () {
  var v = [];
  /* O BNE embute a lista em JSON (com "PathUrlJob") num atributo da página. */
  BV.qa(document, '*').some(function (e) {
    for (var i = 0; i < e.attributes.length; i++) {
      var val = e.attributes[i].value;
      if (val && val.length > 200 && val.indexOf('PathUrlJob') >= 0 && val.charAt(0) === '[') {
        try {
          JSON.parse(val).forEach(function (j) {
            v.push({ titulo: j.Titulo || (j.Function && j.Function.Name) || '', empresa: j.Confidential ? '' : (j.CompanyName || ''),
              cidade: (j.City && j.City.Name) || '', uf: j.StateAbbreviation || '', modalidade: j.Home_Office ? 'remoto' : '',
              contrato: BV.contrato((j.LinkType || []).join(' ')), data: BV.data(j.PostDate || j.ReleaseDate || ''), link: j.Url || '',
              descricao: (j.GeneralDescription || '').slice(0, 300) });
          });
        } catch (x) {}
        return true;
      }
    }
    return false;
  });
  if (!v.length) {
    v = BV.qa(document, '.card--list--vagas').map(function (c) {
      var itens = BV.qa(c, '.info__vaga-item').map(BV.t);
      var local = itens.filter(function (s) { return /\/\s*[A-Z]{2}\s*$/.test(s); })[0] || '';
      var id = c.getAttribute('data-job-id');
      return { titulo: BV.tq(c, 'h2').replace(/^vaga de\s+/i, ''), empresa: itens[1] || '', local: local,
        modalidade: BV.q(c, '.is-home-office') ? 'remoto' : '', link: 'https://www.bne.com.br/vagas-de-emprego/' + id,
        descricao: BV.tq(c, '.info__vaga p') };
    });
  }
  return BV.saida(v);
})()

(function () {
  var v = BV.qa(document, 'article.job-card').map(function (c) {
    var a = BV.q(c, 'a.job-link') || BV.q(c, 'a');
    var badges = BV.tq(c, '.job-badges');
    var det = BV.tq(c, '.job-details');
    var dt = BV.tq(c, '.job-date, time, .job-detail--date, .job-published');
    return { titulo: BV.tq(c, '.job-title').replace(/^\d+\s+vagas?\s+de\s+/i, ''), empresa: BV.tq(c, '.job-company'),
      local: BV.tq(c, '.job-location'), modalidade: BV.q(c, '.job-badge--remote') ? 'remoto' : BV.modalidade(badges),
      contrato: BV.contrato(badges + ' ' + det), data: BV.data(dt), dataTexto: dt, link: a ? a.href : '' };
  });
  return BV.saida(v.length ? v : BV.ld());
})()

(function () {
  var v = [];
  try {
    var pd = window.mosaic && window.mosaic.providerData && window.mosaic.providerData['mosaic-provider-jobcards'];
    var res = pd && pd.metaData && pd.metaData.mosaicProviderJobCardsModel && pd.metaData.mosaicProviderJobCardsModel.results;
    (res || []).forEach(function (j) {
      v.push({ titulo: j.displayTitle || j.title, empresa: j.company, local: j.formattedLocation,
        modalidade: j.remoteLocation ? 'remoto' : BV.modalidade(j.formattedLocation),
        contrato: BV.contrato((j.jobTypes || []).join(' ')), data: j.pubDate ? new Date(j.pubDate).toISOString().slice(0, 10) : BV.data(j.formattedRelativeTime),
        dataTexto: j.formattedRelativeTime || '', link: 'https://br.indeed.com/viewjob?jk=' + j.jobkey,
        descricao: (j.snippet || '').replace(/<[^>]+>/g, ' ').slice(0, 300) });
    });
  } catch (e) {}
  if (!v.length) {
    v = BV.qa(document, '.job_seen_beacon, .cardOutline').map(function (c) {
      var a = BV.q(c, 'h2 a, a.jcs-JobTitle');
      var local = BV.tq(c, '[data-testid="text-location"], .companyLocation');
      var dt = BV.tq(c, '.date, [data-testid="myJobsStateDate"]');
      return { titulo: BV.t(a), empresa: BV.tq(c, '[data-testid="company-name"], .companyName'), local: local,
        modalidade: BV.modalidade(local), dataTexto: dt, data: BV.data(dt), link: a ? a.href : '' };
    });
  }
  return BV.saida(v.length ? v : BV.ld());
})()
